def transform(grid):
    a=[r[:] for r in grid]; n=len(a); m=len(a[0]); bg=max(set(x for r in a for x in r),key=lambda x:sum(r.count(x) for r in a))
    sep_row=next((i for i,r in enumerate(a) if len(set(r))==1 and r[0]!=bg),None)
    sep_col=next((j for j in range(m) if len({a[i][j] for i in range(n)})==1 and a[0][j]!=bg),None)
    if sep_col is not None:
        for i in range(n):
            left=[(j,a[i][j]) for j in range(sep_col) if a[i][j]!=bg and a[i][j]!=a[0][sep_col]]
            right=[(j,a[i][j]) for j in range(sep_col+1,m) if a[i][j]!=bg]
            if left and right:
                jl,x=left[-1]; jr,y=right[0]
                a[i][jr]=bg; a[i][sep_col+1 if x==y else m-1]=y
    else:
        for j in range(m):
            top=[(i,a[i][j]) for i in range(sep_row) if a[i][j]!=bg and a[i][j]!=a[sep_row][0]]
            bottom=[(i,a[i][j]) for i in range(sep_row+1,n) if a[i][j]!=bg]
            if top and bottom:
                it,x=top[-1]; ib,y=bottom[0]
                a[ib][j]=bg; a[sep_row+1 if x==y else n-1][j]=y
    return a
